20	/*!
21	 * \brief ub to ub copy
22	 * \param[in] src, Input LocalTensor
23	 * \param[out] dst, Output LocalTensor
24	 */
25	template <typename OperationShape, typename T>
26	__aicore__ inline void CopyAssign(
27	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src, OperationShape& operationShape)
28	{
29	    AscendC::DataCopy(dst, src, operationShape.axis0);
30	}
31	
32	/*!
33	 * \brief Datacopy from src to dst
34	 * \param[in] src, Input GlobalTensor
35	 * \param[in] copyCnt, Length of copy data
36	 * \param[out] dst, Output LocalTensor
37	 */
38	template <typename T>
39	__aicore__ inline void CopyIn(AscendC::LocalTensor<T> dst, AscendC::GlobalTensor<T> src, uint64_t copyCnt)
40	{
41	    AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(copyCnt * sizeof(T)), 0, 0, 0};
42	    AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
43	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
44	}
45	
46	/*!
47	 * \brief Datacopy from src to dst
48	 * \param[in] src, Input LocalTensor
49	 * \param[in] copyCnt, Length of copy data
50	 * \param[out] dst, Output GlobalTensor
51	 */
52	template <typename T>
53	__aicore__ inline void CopyOut(AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> src, uint64_t copyCnt)
54	{
55	    AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(copyCnt * sizeof(T)), 0, 0, 0};
56	    AscendC::DataCopyPad(dst, src, copyParams);
57	}
58	
59	// Partial specialization for CopyIn(E)
60	template <typename T>
61	struct Evaluator<OpCopyIn<T>> {
62	    using Type = void;
63	
64	    template <typename Context>
65	    __aicore__ inline auto operator()(const OpCopyIn<T>& op, Context& context) const
66	    {
67	        auto& obj = Evaluator<T>{}(op.GetData(), context);
68	        uint32_t bufferId =
69	            Atvoss::Ele::Tile::GetBufferId<typename Context::BuffMaps, T::number, Atvoss::Ele::Tile::BufType::PARAM>(
70	                context.pingPong);
71	        // AscendC::printf("OpCopyIn, IN[%u]-[%u] context.pingPong: %u\n", T::number, bufferId, context.pingPong);
72	#if _ATVOSS_ARCH35_
73	        AscendC::Mutex::Lock<PIPE_MTE2>(bufferId);
74	#else
75	        AscendC::PipeBarrier<PIPE_ALL>();
76	#endif
77	        obj.CopyIn(context.gmOffset, context.elementNum);
78	#if _ATVOSS_ARCH35_
79	        AscendC::Mutex::Unlock<PIPE_MTE2>(bufferId);
80	        AscendC::Mutex::Lock<PIPE_V>(bufferId);
81	#else
82	        AscendC::PipeBarrier<PIPE_ALL>();
83	#endif
84	    }
85	};
86	
87	// Partial specialization for CopyOut(E)
88	template <typename T>
89	struct Evaluator<OpCopyOut<T>> {
90	    using Type = void;
91	
92	    template <typename Context>
93	    __aicore__ inline auto operator()(const OpCopyOut<T>& op, Context& context) const
94	    {
95	        uint32_t bufferId =
96	            Atvoss::Ele::Tile::GetBufferId<typename Context::BuffMaps, T::number, Atvoss::Ele::Tile::BufType::PARAM>(
97	                context.pingPong);
98	        // AscendC::printf("OpCopyIn, IN[%u]-[%u] context.pingPong: %u\n", T::number, bufferId, context.pingPong);
99	#if _ATVOSS_ARCH35_
100	        AscendC::Mutex::Unlock<PIPE_V>(bufferId);
101	        AscendC::Mutex::Lock<PIPE_MTE3>(bufferId);
102	#else
103	        AscendC::PipeBarrier<PIPE_ALL>();
104	#endif
105	        auto& obj = Evaluator<T>{}(op.GetData(), context);
106	        obj.CopyOut(context.gmOffset, context.elementNum);
107	#if _ATVOSS_ARCH35_
108	        AscendC::Mutex::Unlock<PIPE_MTE3>(bufferId);
109	#else
110	        AscendC::PipeBarrier<PIPE_ALL>();
111	#endif
112	    }
113	};
