115	// Partial specialization for OpCopy(E)
116	template <typename T, typename U>
117	struct Evaluator<OpAssign<T, OpCopy<U>>> {
118	public:
119	    using Type = void;
120	
121	    template <typename Context>
122	    __aicore__ inline auto operator()(const OpAssign<T, OpCopy<U>>& op, Context& context) const
123	    {
124	        using Dtype = Dtype_t<T>;
125	        auto operationShape = GetShape<Operation::Unary>(context.argsTensors);
126	        // UB to UB copy
127	        return Atvoss::Tile::CopyAssign(
128	            Evaluator<T>{}(op.GetLhs(), context).GetUbTensor(),
129	            Evaluator<U>{}(op.GetRhs().GetData(), context).GetUbTensor(), operationShape);
130	    }
131	};
