30	
31	using Atvoss::Util::Find_v;
32	using Atvoss::Util::Get_t;
33	using Atvoss::Util::Size_v;
34	using Atvoss::Util::Reverse_t;
35	
36	template <typename ExprList, MemMngPolicy memMngPolicy, typename = void>
37	struct DagSelector {
38	    using Type = Atvoss::Ele::Tile::ManualDag<ExprList>;
39	};
40	
41	template <typename ExprList, MemMngPolicy memMngPolicy>
42	struct DagSelector<ExprList, memMngPolicy, std::enable_if_t<memMngPolicy == MemMngPolicy::AUTO>> {
43	    using Type = Atvoss::Ele::Tile::FullAutoDag<ExprList>;
44	};
45	
46	template <typename Expression, typename D>
47	struct ComputeInfo {
48	    using Expr = typename Expression::Type;
49	    using Dag = D;
50	};
51	
52	template <MemMngPolicy memMngPolicy = MemMngPolicy::AUTO, typename T>
53	__host_aicore__ constexpr auto PreProcessComputeExpr(const Expression<T>& expr)
54	{
55	    using ExprT = T;
56	    using OriExprList = typename Atvoss::FlattenAtOpAndThen<ExprT>::Type;
57	    static_assert(Size_v<OriExprList> > 0, "Compute expression is empty.");
58	
59	    // 1. Dag
60	    using DagX = typename DagSelector<OriExprList, memMngPolicy>::Type;
61	    // 2. Add OpAlloc before its first use & OpFree after its last use
62	    using ExprListWithCopyX = typename DagX::ExprListWithCopyX;
63	    using ParamUseList = typename DagX::ParamUseList;
64	    using LocalVarUseList = typename DagX::LocalVarUseList;
65	    auto result1 = ForEach(Reverse_t<ParamUseList>{}, Atvoss::Graph::AllocInserter{}, ExprListWithCopyX{});
66	    auto result2 = ForEach(ParamUseList{}, Atvoss::Graph::FreeInserter{}, result1);
67	    auto result3 = ForEach(Reverse_t<LocalVarUseList>{}, Atvoss::Graph::AllocInserter{}, result2);
68	    auto result4 = ForEach(LocalVarUseList{}, Atvoss::Graph::FreeInserter{}, result3);
69	    // 3. Rebuild Expression
70	    using LastExpression = typename BuildExpression<decltype(result4)>::Type;
71	    return ComputeInfo<LastExpression, DagX>{};
72	};
73	
74	template <uint32_t UB_TILE_SIZE, uint32_t USER_TILE_SIZE>
75	struct TileCheckAssert {
76	    static_assert(USER_TILE_SIZE <= UB_TILE_SIZE, "user's tile size can not be bigger than Ub tile size.");
77	};
78	
79	template <typename Compute, const auto& Policy, typename ScheduleCfg, typename ArchTagCfg = void>
80	class BaseBlockSchedule {
81	public:
82	    using ExpressMaker = Compute;
83	    using ParamStruct = ScheduleCfg;
84	    using BlockPolicy = typename std::remove_reference<decltype(Policy)>::type;
85	    using ArchTag = ArchTagCfg;
86	    using TileShape = typename BlockPolicy::TileShape;
87	    // number of elements in Tile calculation
88	    static constexpr uint32_t BASIC_BLOCK = Atvoss::Tile::GetTotalElement<0, BlockPolicy>(1, 1);
89	
90	private:
91	    // alignment of constants
92	    static constexpr uint32_t ALIGNMENT = 32;
93	
94	    /* ----------------Prepare param ---------------- */
95	    using ShapeT = Atvoss::Tile::Shape_t<typename std::remove_reference<decltype(Policy)>::type>;
96	    using ShapeSize = Atvoss::Tile::ShapeSize<ShapeT>;
97	
98	    static constexpr uint32_t GetLayoutAxis0()
99	    {
100	        static_assert(ShapeSize::value <= 2, "[ERROR]: [Atvoss][Block] Tile shape can not be greater than 2!");
101	        if constexpr (ShapeSize::value == 2) {
102	            using DstShape0Type = typename ShapeT::template get_type<0>;
103	            static_assert((DstShape0Type::value > 0), "[ERROR]: [Atvoss][Block] Shape axis0 must not be zero");
104	            return DstShape0Type::value;
105	        }
106	        return BASIC_BLOCK;
107	    }
108	    static constexpr uint32_t GetLayoutAxis1()
109	    {
110	        static_assert(ShapeSize::value <= 2, "[ERROR]: [Atvoss][Block] Tile shape can not be greater than 2!");
111	        if constexpr (ShapeSize::value == 2) {
112	            using DstShape1Type = typename ShapeT::template get_type<1>;
113	            static_assert((DstShape1Type::value > 0), "[ERROR]: [Atvoss][Block] Shape axis1 must not be zero");
114	            return DstShape1Type::value;
115	        }
116	        return 1;
117	    }
118	
119	    template <typename T>
120	    using BlockTensorTile = Atvoss::Ele::BlockTensor<
121	        T, Atvoss::Layout::Layout<Atvoss::Layout::FixedRankExtents<BASIC_BLOCK, GetLayoutAxis0(), GetLayoutAxis1()>>>;
122	    static constexpr auto computeRes = ToLinearizerExpr(Compute{}.template Compute<BlockTensorTile>());
123	    static constexpr auto optimizedCompute = PreProcessComputeExpr<Policy.memPolicy>(computeRes);
124	    using ComputeInfoT = decltype(optimizedCompute);
125	    using ExprTile = typename ComputeInfoT::Expr;
126	    using EleWiseDag = typename ComputeInfoT::Dag;
127	    // Remember-1: Size_v<Params> <= Size_v<InParams> + Size_v<OutParams>
128	    // Remember-2: Params comes from `Optimized` Dag rather than the original one.
129	    using Params = typename EleWiseDag::AllParams;
130	    using InParams = typename EleWiseDag::InParams;
131	    using OutParams = typename EleWiseDag::OutParams;
132	    using LocalVars = typename EleWiseDag::AllLocalVars;
133	
134	    static constexpr uint32_t IN_PARAMS_COUNT = Size_v<InParams> * 2;
135	    static constexpr uint32_t OUT_PARAMS_COUNT = Size_v<OutParams> * 2;
136	    static constexpr uint32_t LOCAL_VAR_COUNT = Size_v<LocalVars>;
137	
138	    static constexpr uint32_t MAX_BUFFER_COUNT = IN_PARAMS_COUNT + OUT_PARAMS_COUNT + LOCAL_VAR_COUNT;
139	    static constexpr uint32_t UB_TILE_SIZE = ArchTag::UB_SIZE / MAX_BUFFER_COUNT / 1024 * 1024;
140	    static constexpr uint64_t UB_ADDR_IN = 0;
141	    static constexpr uint64_t UB_ADDR_OUT = UB_TILE_SIZE * IN_PARAMS_COUNT;
142	    static constexpr uint64_t UB_ADDR_CALC = UB_ADDR_OUT + UB_TILE_SIZE * OUT_PARAMS_COUNT;
143	
144	    /* ----------------Calc element count in a tensor start---------------- */
145	    template <size_t N, typename Params>
146	    static constexpr int FindParamsMaxTypeSizeImpl(int defaultSize = 1)
147	    {
148	        using ParamType = Get_t<Params, N>;
149	        if constexpr (!std::is_scalar_v<typename ParamType::Type>) {
150	            using DType = typename ParamType::Type::PrimType;
151	            if (defaultSize < sizeof(DType)) {
152	                defaultSize = sizeof(DType);
153	            }
154	        }
155	
156	        constexpr int len = Size_v<Params>;
157	        if constexpr (N < len - 1) {
158	            return FindParamsMaxTypeSizeImpl<N + 1, Params>(defaultSize);
159	        }
160	        return defaultSize;
161	    }
162	
163	    template <typename Params>
164	    static constexpr uint32_t FindParamsMaxTypeSize()
165	    {
166	        return FindParamsMaxTypeSizeImpl<0, Params>();
167	    }
168	
169	    static constexpr uint32_t MaxSize = FindParamsMaxTypeSize<Params>();
170	
171	    /*!
172	     * \brief Get the size of UB space occupied by a single node during compilation.
173	     * \return uint32_t. Maximum number of elements allocated in a single node.
174	     */
175	    static constexpr uint32_t GetEleCntInTensor()
176	    {
177	        if constexpr (ShapeSize::value == 2) {
178	            using DstShape1Type = typename ShapeT::template get_type<1>;
179	            return ((UB_TILE_SIZE / MaxSize) + DstShape1Type::value - 1) / DstShape1Type::value;
180	        }
181	        return ((UB_TILE_SIZE / MaxSize) + ALIGNMENT - 1) / ALIGNMENT;
182	    }
183	
184	    static constexpr uint32_t ELEMENT_COUNT_IN_TENSOR = GetEleCntInTensor();
185	    /* ----------------Calc element count in a tensor end---------------- */
186	
187	public:
188	    /*!
189	     * \brief Configure Block Param during compilation.
190	     * \param[in] blockParam, Block ScheduleCfg(Config).
191	     * \return bool. Return true to indicate calculation success.
192	     */
193	    template <typename Args, typename KernelScheduleCfg>
194	    static bool MakeScheduleConfig(
195	        const Args& arguments, const KernelScheduleCfg& kernelConfig, ScheduleCfg& blockConfig)
196	    {
197	        printf("[DEBUG]: [Atvoss][BlockSchedule] MakeScheduleConfig for block!\n");
198	        printf("[DEBUG]: [Atvoss][BlockSchedule] MemPolicy is %d.\n", static_cast<int>(Policy.memPolicy));
199	        return true;
200	    }
201	
202	#if !defined(__ATVOSS_HOST_ONLY__)
203	public:
204	    /*!
205	     * \brief Default constructor
206	     */
207	    __aicore__ inline BaseBlockSchedule()
208	    {
209	        if constexpr (UB_TILE_SIZE < (BASIC_BLOCK * MaxSize + ALIGNMENT - 1) / ALIGNMENT * ALIGNMENT) {
210	            TileCheckAssert<UB_TILE_SIZE, (BASIC_BLOCK * MaxSize + ALIGNMENT - 1) / ALIGNMENT * ALIGNMENT> dummy;
211	        }
212	
213	        bufPools_.Init();
214	    }
215	
216	    /*!
217	     * \brief Block layer execution function.
218	     * \param[in] cfg, Segmentation of tile in block.
219	     * \param[in] argTuple, Input and output data in GM.
220	     */
221	    template <typename ArgTup>
222	    __aicore__ inline void Run(ScheduleCfg& cfg, ArgTup& argTuple)
223	    {
224	        cfg.wholeLoop = cfg.totalElemCnt / BASIC_BLOCK;
225	        cfg.tileCnt = cfg.totalElemCnt % BASIC_BLOCK;
226	        Process(cfg, argTuple);
227	    }
228	
229	private:
230	    template <typename ArgTup>
231	    __aicore__ inline void Process(ScheduleCfg& cfg, ArgTup& argTuple)
232	    {
233	        auto blockLocalVars = PrepareParams<LocalVars>();
234	        auto blockTensorsTile = PrepareBlockParams<Params>(argTuple);
235	        using BufferMaps = typename EleWiseDag::BufMap;
236	        using ContextDataT =
237	            ContextData<decltype(blockTensorsTile), decltype(blockLocalVars), decltype(bufPools_), BufferMaps>;
238	
239	        uint32_t i = 0;
240	        for (; i < cfg.wholeLoop; i++) {
241	            ContextDataT context{blockTensorsTile, blockLocalVars, bufPools_, i * BASIC_BLOCK, BASIC_BLOCK, i & 1};
242	            Atvoss::Ele::Tile::Evaluate<ExprTile>(context);
243	        }
244	        if (cfg.tileCnt > 0) {
245	            ContextDataT context{blockTensorsTile, blockLocalVars, bufPools_, i * BASIC_BLOCK, cfg.tileCnt, i & 1};
246	            Atvoss::Ele::Tile::Evaluate<ExprTile>(context);
247	        }
248	    }
249	
250	    template <typename ParamType>
251	    __aicore__ inline auto ConstructParam()
252	    {
253	        return ConstructParam<ParamType>(HasUsage<ParamType>{});
254	    }
255	
256	    template <typename ParamType>
257	    __aicore__ inline auto ConstructParam(std::false_type)
258	    {
259	        using DType = typename ParamType::Type::PrimType;
260	        return BlockTensorTile<DType>{};
261	    }
262	
263	    template <typename Params, size_t... Ints>
264	    __aicore__ inline auto PrepareParamsImpl(AscendC::Std::index_sequence<Ints...>)
265	    {
266	        return AscendC::Std::make_tuple(ConstructParam<Get_t<Params, Ints>>()...);
267	    }
268	
269	    template <typename Params>
270	    __aicore__ inline auto PrepareParams()
271	    {
272	        return PrepareParamsImpl<Params>(AscendC::Std::make_index_sequence<Size_v<Params>>{});
273	    }
274	
275	    template <typename ParamType, typename ArgTup>
276	    __aicore__ inline constexpr auto ConstructBlockParam(ArgTup& args)
277	    {
278	        // We use `inplaceNumber` to adapter IN_OUT params optimization in `AUTO` Dag
279	        constexpr auto argNumber = ParamType::inplaceNumber - 1;
