38	{
39	    PERSIST_MTE2 = 0,
40	    MTE2,
41	    PERSIST_MTE3,
42	    MTE3,
43	    PERSIST_TEMP,
44	    TEMP,
45	    PONG_MTE3,
46	    MAX_POS,
