49	constexpr static std::size_t BUF_ALLOCATED_IDX = static_cast<std::size_t>(BufPosInList::MAX_POS);
50	constexpr static std::size_t BUF_TO_RELEASE_IDX = static_cast<std::size_t>(BufPosInList::MAX_POS);
51	
52	constexpr static uint32_t BUF_MTE2 = 0b00'001;
53	constexpr static uint32_t BUF_MTE3 = 0b00'010;
54	constexpr static uint32_t BUF_TEMP = 0b00'100;
55	constexpr static uint32_t BUF_PLACEHOLDER = 0b01'000;
56	constexpr static uint32_t BUF_SCALAR = 0b10'000;
57	
58	constexpr static uint32_t BUF_PING = 0b000'01;
59	constexpr static uint32_t BUF_PONG = 0b000'10;
60	
61	constexpr static uint8_t BUF_COMBINE_SHIFT = 5;
62	constexpr static uint32_t BUF_COMBINE_MASK = 0x1F;
63	constexpr static uint8_t BUF_COMBINED_MAX = 5;
64	
65	constexpr static uint8_t BUF_PING_PONG = 2;
66	constexpr static uint8_t BUF_MAX_COUNT = 32;
67	
68	template <std::size_t N, BufType bt, uint32_t pingId, uint32_t pongId>
69	struct ParamBufIdMap {
70	    static const std::size_t paramNum = N;
71	    static const BufType bufType = bt;
72	    static const uint32_t pingBufId = pingId;
73	    static const uint32_t pongBufId = pongId;
74	};
75	
76	template <std::size_t N, BufType bt, std::size_t pongOffset, std::size_t bufIdOffset = 0, typename TL = TypeList<>>
77	struct ParamBufIdMapGenerator {
78	private:
79	    static constexpr uint32_t pingId = static_cast<uint32_t>(N - 1 + bufIdOffset);
80	    static constexpr uint32_t pongId = static_cast<uint32_t>(bt == BufType::PARAM ? pingId + pongOffset : pingId);
81	
82	public:
83	    using Type = Append_t<
84	        typename ParamBufIdMapGenerator<N - 1, bt, pongOffset, bufIdOffset, TL>::Type,
85	        ParamBufIdMap<N, bt, pingId, pongId>>;
86	};
87	
88	template <BufType bt, std::size_t pongOffset, std::size_t bufIdOffset, typename TL /*TypeList*/>
89	struct ParamBufIdMapGenerator<0, bt, pongOffset, bufIdOffset, TL> {
90	    using Type = TL;
91	};
92	
93	template <std::size_t paramCount, std::size_t localVarCount>
94	struct GenerateBufferId {
95	private:
96	    using ParamBuf = typename ParamBufIdMapGenerator<
97	        paramCount, BufType::PARAM,
98	        /*PongOffset=*/paramCount + localVarCount>::Type;
99	    using LocalBuf = typename ParamBufIdMapGenerator<
100	        localVarCount, BufType::LOCAL_VAR,
101	        /*PongOffset=*/paramCount + localVarCount,
102	        /*BufIdOffset=*/paramCount>::Type;
103	
104	public:
105	    using Type = Concatenate_t<ParamBuf, LocalBuf>;
106	};
107	
108	// Buffer wrapper Tempalte
109	template <int32_t bufId, uint32_t bufUsage, uint32_t where = BUF_PING>
110	struct BufferWrapper {
111	    // < 0 means no buffer will be allocated
112	    // only a placeholder to make schedule happy.
113	    constexpr static int32_t bufferId = bufId;
114	    constexpr static uint32_t bufferUsage = bufUsage;
115	    constexpr static uint32_t pingPong = where;
116	};
117	
118	// Template used to generate buffer wrappers.
119	template <
120	    std::size_t count, uint32_t bufUsage, uint32_t bufIdOffset = 0, uint32_t where = BUF_PING,
121	    typename ResultList = TypeList<>, typename = void>
122	struct GenerateBufferWrappers {
123	    using Type = Append_t<
124	        typename GenerateBufferWrappers<count - 1, bufUsage, bufIdOffset, where, ResultList>::Type,
125	        BufferWrapper<count - 1 + bufIdOffset, bufUsage, where>>;
126	};
127	
128	template <std::size_t count, uint32_t bufUsage, uint32_t bufIdOffset, uint32_t where, typename ResultList>
129	struct GenerateBufferWrappers<count, bufUsage, bufIdOffset, where, ResultList, std::enable_if_t<count <= 0>> {
130	    using Type = TypeList<>;
131	};
132	
133	// Map to store relationship from bind to buffers.
134	template <typename B, typename... Ts>
135	struct Mapping {
136	    using Bind = B;
137	    using Buffers = TypeList<Ts...>;
138	};
139	
140	template <typename B>
141	struct MappingBindEqual {
142	    template <typename M>
143	    using Type = std::is_same<typename M::Bind, B>;
144	};
145	
146	template <typename Ms, typename B>
147	using MappingFind_t = Filter_t<MappingBindEqual<B>::template Type, Ms>;
148	
149	// To Combine several buffers used in one Node.
150	// At most 5 (5*5 = 25 < 32. uint32_t has 32 bits).
151	template <typename... Ts>
152	struct CombineBufferWrapper {};
153	
154	template <typename T>
155	struct CombineBufferWrapper<T> {
156	    constexpr static uint32_t bufferId = static_cast<uint32_t>(T::bufferId);
157	    constexpr static uint32_t bufferUsage = T::bufferUsage;
158	    constexpr static uint32_t pingPong = T::pingPong;
159	};
160	
161	template <typename T, typename... Ts>
162	struct CombineBufferWrapper<T, Ts...> {
163	    constexpr static uint32_t bufferId = static_cast<uint32_t>(T::bufferId) << (BUF_COMBINE_SHIFT * sizeof...(Ts)) |
164	                                         CombineBufferWrapper<Ts...>::bufferId;
165	    constexpr static uint32_t bufferUsage =
166	        T::bufferUsage << (BUF_COMBINE_SHIFT * sizeof...(Ts)) | CombineBufferWrapper<Ts...>::bufferUsage;
167	    constexpr static uint32_t pingPong =
168	        T::pingPong << (BUF_COMBINE_SHIFT * sizeof...(Ts)) | CombineBufferWrapper<Ts...>::pingPong;
169	    ;
170	};
171	
172	// Combined buffer wrapper template
173	template <typename... Ts>
174	struct CombinedBufferWrappers : BufferWrapper<
175	                                    static_cast<int>(
176	                                        static_cast<uint32_t>(sizeof...(Ts)) << (BUF_COMBINE_SHIFT * BUF_COMBINED_MAX) |
177	                                        CombineBufferWrapper<Ts...>::bufferId),
178	                                    CombineBufferWrapper<Ts...>::bufferUsage, CombineBufferWrapper<Ts...>::pingPong> {};
179	
180	// Calculate Pong Buffer ID as per @bufferId and @pongOffset.
181	static constexpr int32_t CalcPongBufferId(
182	    int32_t bufferId, uint32_t bufferUsage, uint32_t pingPong, uint32_t pongOffset)
183	{
184	    if (pingPong > BUF_PONG) {
185	        // combined buffer wrapper.
186	        // bufferUsage/id/pingPong will always non-negative.
187	        if (pingPong == 0) {
188	            return 0;
189	        } else {
190	            const uint32_t id = static_cast<uint32_t>(bufferId) & BUF_COMBINE_MASK;
191	            const uint32_t usage = bufferUsage & BUF_COMBINE_MASK;
192	            const uint32_t pp = pingPong & BUF_COMBINE_MASK;
193	            const uint32_t currentId =
194	                pp == BUF_PING ? (bufferUsage == BUF_TEMP ? id : (id + pongOffset)) : (id - pongOffset);
195	            const int32_t idNext = static_cast<int32_t>(static_cast<uint32_t>(bufferId) >> BUF_COMBINE_SHIFT);
196	            const uint32_t usageNext = bufferUsage >> BUF_COMBINE_SHIFT;
197	            const uint32_t ppNext = pingPong >> BUF_COMBINE_SHIFT;
198	            return static_cast<int32_t>(
199	                static_cast<uint32_t>(CalcPongBufferId(idNext, usageNext, ppNext, pongOffset)) << BUF_COMBINE_SHIFT |
200	                currentId);
201	        }
202	    } else {
203	        // pure buffer wrapper
204	        return pingPong == BUF_PING ? ((bufferUsage == BUF_TEMP || bufferUsage == BUF_SCALAR) ?
205	                                           bufferId :
206	                                           (bufferUsage == BUF_PLACEHOLDER ? -1 : (bufferId + pongOffset))) :
207	                                      (bufferId - pongOffset);
208	    }
209	}
210	
211	// Extract PingPong BufferID from `AllocList`
212	template <typename Ts, uint32_t pongOffset>
213	struct ExtractBufferId {};
214	
215	template <typename... Ts, uint32_t pongOffset>
216	struct ExtractBufferId<TypeList<Ts...>, pongOffset> {
217	    static constexpr size_t size = sizeof...(Ts);
218	    constexpr static int32_t arr[2][size] = {
